@prefix cdifd: <https://cdif.org/validation/0.1/shacl#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/SpatialExtentBox_my8> ;
            sh:resultMessage "Recommended: provide a spatial coverage description if applicable using schema:Place, identified by a place name, an identifier, point location(s) (GeoCoordinates), or GeoShape (bounding box, line profile location, or polygon)." ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:OrConstraintComponent ;
            sh:sourceShape cdifd:spatialExtentProperty ;
            sh:value <https://example.org/SpatialExtentBox_my8> ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
